 for(const change of[s=>{s.principal.human_write_enabled=false;},s=>{s.principal.workspace_roles={};},s=>{s.principal.expires_at='2000-01-01T00:00:00Z';},
  s=>{s.principal.subject='';},s=>{s.busy=true;},s=>{s.dirty=true;}]){
  const s=state();change(s);const h=harness({s});assert.equal(await h.run(),false);assert.equal(h.calls.length,0);assert.equal(h.memory.size,0);}
